        }
        delta ~ normal(0,100);
        for (k in 1:2) { // not necessary when support of sigma is bounded on both sides
            sigma[k] ~ uniform(0, 100);
        }
        sigmay ~ uniform(0, 100); // not necessary when support of sigmay is bounded on both sides
